// Banner istituzionale incorporato offline dal file banner_scuola_4e0c1863.png (709x150 RGBA)
export const SCHOOL_BANNER_WIDTH = 709;
export const SCHOOL_BANNER_HEIGHT = 150;
export const SCHOOL_BANNER_BASE64 = '';

let cachedBytes: Uint8Array | null = null;

export function getSchoolBannerUint8Array(): Uint8Array {
  if (cachedBytes) return cachedBytes;
  const binary = atob(SCHOOL_BANNER_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  cachedBytes = bytes;
  return bytes;
}

export function getSchoolBannerDataUrl(): string {
  return 'data:image/png;base64,' + SCHOOL_BANNER_BASE64;
}
